files=[exe,repo/'src/session.hpp',repo/'tests/backend/main.cpp',repo/'tests/backend/cold_projects.hpp',repo/'tests/backend/midi_engine.hpp',repo/'tests/backend/midi_transport.hpp',repo/'tests/backend/plugin_recovery.hpp',repo/'tests/backend/tail_cases.hpp',repo/'tests/backend/stem_cases.hpp',repo/'tests/backend/freeze_cases.hpp',repo/'tests/backend/freeze_extended.hpp',repo/'tests/backend/freeze_guard_cases.hpp',repo/'tests/backend/pdc_extended.hpp',repo/'tests/backend/pdc_hosted.hpp',repo/'tests/backend/plugin_workflow.hpp',repo/'src/plugin_chain.hpp',repo/'tests/backend/routing_template.hpp',repo/'tests/backend/project_faults.hpp',repo/'tests/backend/stem_nonlinear.hpp',repo/'tests/backend/midi_loop.hpp',repo/'tests/gain_fixture.cpp',repo/'tests/plugin_fixture_helpers.hpp',repo/'src/plugin_scan.hpp',repo/'tests/backend/scan_fault_fixture.cpp',repo/'src/stem_job.hpp',repo/'src/export_job.hpp',repo/'src/render_guard.hpp',repo/'src/input_watch.hpp',repo/'src/staging_copy.hpp',repo/'tests/backend/copy_watchdog.hpp',repo/'tests/backend/render_guard_cases.hpp',repo/'tests/backend/stem_job_cases.hpp',repo/'tests/backend/tail_fixture.cpp',*(repo/'build/backend/StudioTestTail_artefacts/Release/VST3').rglob('*.vst3'),repo/'tests/backend/midi_fixture.cpp',*(repo/'build/backend/StudioMidiFixture_artefacts/Release/VST3').rglob('*.vst3'),*fixture.rglob('*.vst3'),repo/'tests/backend/delay_fixture.cpp',repo/'tests/backend/CMakeLists.txt',* (repo/'build/backend/StudioTestDelay_artefacts/Release/VST3').rglob('*.vst3')]
